// profiling in the Editor: wait for Burst instead of running managed code first
[BurstCompile(CompileSynchronously = true)]
struct NeighboursJob : IJobParallelFor { /* ... */ }
// or Jobs > Burst > Synchronous Compilation, then let it warm up a few frames

// more reliable: a Development Build on the target device,
// the same ProfilerMarker, the same scene, before and after

using Unity.Profiling;

static readonly ProfilerMarker s_Neighbours = new ProfilerMarker("Units.Neighbours");

void Update()
{
    using (s_Neighbours.Auto())   // shows up in the Profiler: Hierarchy and Timeline
    {
        FindNeighbours();
    }
}

// AoS: one struct per unit; a speed loop drags every field through the cache
struct Unit { public float3 position; public quaternion rotation; public float speed; }
NativeArray<Unit> units;

// SoA: one array per field; the speed loop reads contiguous floats only
NativeArray<float> speeds;

// Jobs > Burst > Open Inspector, "Highlight SIMD Scalar vs Packed":
//   mulss          -> one float per instruction (scalar)
//   mulps / vmulps -> 4 or 8 floats per instruction (packed)

JobHandle handle;

void Update()
{
    handle = new NeighboursJob { positions = positions, result = result }
        .Schedule(positions.Length, 64);
    JobHandle.ScheduleBatchedJobs();   // the workers start now
}

void LateUpdate()
{
    handle.Complete();   // Timeline: is there a long WaitForJobGroupID here?
    ApplyNeighbours(result);
}
